CREATE TYPE order_source AS ENUM ('DINE_IN','WALK_IN','TAKEAWAY','WEBSITE','SWIGGY','ZOMATO');
CREATE TYPE order_status AS ENUM ('RECEIVED','ACCEPTED','PREPARING','READY','SERVED','COMPLETED','CANCELLED');
CREATE TABLE users (id serial PRIMARY KEY,name varchar(120) NOT NULL,email varchar(255) NOT NULL UNIQUE,password_hash text NOT NULL,role varchar(40) NOT NULL,active boolean NOT NULL DEFAULT true,created_at timestamptz NOT NULL DEFAULT now());
CREATE TABLE cafe_tables (id serial PRIMARY KEY,table_number varchar(20) NOT NULL UNIQUE,qr_token varchar(100) NOT NULL UNIQUE,active boolean NOT NULL DEFAULT true);
CREATE TABLE menu_categories (id serial PRIMARY KEY,name varchar(100) NOT NULL,sort_order integer NOT NULL DEFAULT 0,active boolean NOT NULL DEFAULT true);
CREATE TABLE menu_items (id serial PRIMARY KEY,category_id integer REFERENCES menu_categories(id),name varchar(160) NOT NULL,description text,price_paise integer NOT NULL CHECK(price_paise>=0),available boolean NOT NULL DEFAULT true,demo_data boolean NOT NULL DEFAULT false,created_at timestamptz NOT NULL DEFAULT now());
CREATE TABLE orders (id serial PRIMARY KEY,order_number varchar(40) NOT NULL UNIQUE,source order_source NOT NULL,status order_status NOT NULL DEFAULT 'RECEIVED',table_id integer REFERENCES cafe_tables(id),external_platform_order_id varchar(120),customer_name varchar(120),subtotal_paise integer NOT NULL,tax_paise integer NOT NULL DEFAULT 0,discount_paise integer NOT NULL DEFAULT 0,total_paise integer NOT NULL,payment_status varchar(30) NOT NULL DEFAULT 'PENDING',demo_data boolean NOT NULL DEFAULT false,created_at timestamptz NOT NULL DEFAULT now());
CREATE INDEX orders_created_at_idx ON orders(created_at); CREATE INDEX orders_source_idx ON orders(source);
CREATE TABLE order_items (id serial PRIMARY KEY,order_id integer NOT NULL REFERENCES orders(id),menu_item_id integer REFERENCES menu_items(id),item_name_snapshot varchar(160) NOT NULL,quantity integer NOT NULL CHECK(quantity>0),unit_price_paise integer NOT NULL,notes text);
CREATE INDEX order_items_order_id_idx ON order_items(order_id);
CREATE TABLE invoices (id serial PRIMARY KEY,order_id integer NOT NULL REFERENCES orders(id),invoice_number varchar(50) NOT NULL UNIQUE,subtotal_paise integer NOT NULL,tax_paise integer NOT NULL,discount_paise integer NOT NULL,total_paise integer NOT NULL,payment_status varchar(30) NOT NULL,issued_at timestamptz NOT NULL DEFAULT now());
CREATE UNIQUE INDEX invoices_order_id_unique ON invoices(order_id);
CREATE TABLE order_status_events (id serial PRIMARY KEY,order_id integer NOT NULL REFERENCES orders(id),from_status varchar(30),to_status varchar(30) NOT NULL,note text,created_at timestamptz NOT NULL DEFAULT now()); CREATE INDEX order_status_events_order_id_idx ON order_status_events(order_id);
CREATE TABLE expenses (id serial PRIMARY KEY,category varchar(100) NOT NULL,description text NOT NULL,amount_paise integer NOT NULL,incurred_at timestamptz NOT NULL,demo_data boolean NOT NULL DEFAULT false,created_at timestamptz NOT NULL DEFAULT now());
CREATE TABLE audit_logs (id serial PRIMARY KEY,actor_user_id integer REFERENCES users(id),action varchar(100) NOT NULL,entity_type varchar(80) NOT NULL,entity_id varchar(80),details text,created_at timestamptz NOT NULL DEFAULT now());
